            return {}

        counts = {}
        for char in test:
            counts[char] = counts.get(char, 0) + 1

        max_count = 0
        max_char = ''
        for char, count in counts.items():
            if count > max_count:
                max_count = count
                max_char = char
        return {'a': max_char, 'b': max_char, 'c': max_char}
    except Exception as e:
        print(f"Error: {e}")
        return {}
