def is_nested(string):
    """
    Checks if a string contains a valid subsequence of brackets where at least one bracket in the subsequence is nested.

    Args:
        string: The string to check.

    Returns:
        True if the string contains a valid subsequence of brackets, False otherwise.
    """
    stack = []
    for char in string:
        if char in ['[', ']', ']]':
            stack.append(char)
    for char in string:
        if char in ['[', ']', ']]':
            if len(stack) > 0:
                return True
            else:
                print(f"Invalid character: {char}")
                return False
        else:
            stack.append(char)
    return False
