        largest = lst[0]
        smallest = lst[0]

        for num in lst:
            if num > largest:
                largest = num
            if num < smallest:
                smallest = num

        return (largest, smallest)
    except (TypeError, ValueError) as e:
    print(f"Error: Could not find the largest or smallest element in the list. {e}")
    return (None, None)
