def max_fill(grid, capacity):
    n = len(grid)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if grid[i][j] == 0:
                if i > 0:
                    dp[i][j] = min(dp[i][j], dp[i-1][j] + 1)
                if j > 0:
                    dp[i][j] = min(dp[i][j], dp[i][j-1] + 1)

    return dp[n-1][n-1]
