def do_algebra(operator, operand):
    if len(operator) != len(operand):
        return "Error: Length of operator list must equal the length of operand list."

    result = 0
    for i in range(len(operator)):
        if operator[i] == '+':
            result += operand[i]
        elif operator[i] == '-':
            result -= operand[i]
        elif operator[i] == '*':
            result *= operand[i]
        elif operator[i] == '//':
            if operand[i] == 0:
                return "Error: Division by zero"
            result //= operand[i]
        elif operator[i] == '**':
            result **= operand[i]
    return result
