from collections import deque

def minPath(grid, k):
    n = len(grid)
    q = deque()
    visited = set()
    result = []

    for i in range(n):
        for j in range(n):
            q.append(((i, j), [grid[i][j]], 1))
            visited.add((i, j))

    while q:
        (row, col), path, steps = q.popleft()

        if steps == k:
            if not result or path < result:
                result = path
            continue

        neighbors = []
        if row > 0:
            neighbors.append((row - 1, col))
        if row < n - 1:
            neighbors.append((row + 1, col))
        if col > 0:
            neighbors.append((row, col - 1))
        if col < n - 1:
            neighbors.append((row, col + 1))

        for r, c in neighbors:
            if (r, c) not in visited:
                visited.add((r, c))
                q.append(((r, c), path + [grid[r][c]], steps + 1))

    return result
```

