        if remaining_sum % 2 == 0:
            for j in range(2, remaining_sum // 2 + 1, 2):
                remaining_sum_2 = remaining_sum - j
                if remaining_sum_2 % 2 == 0:
                    for k in range(2, remaining_sum_2 // 2 + 1, 2):
                        if remaining_sum_2 - k == 0:
                            return True
    return False
